import hmac
import hashlib
import struct
import time
import os
from flask import Flask, request, jsonify, abort

app = Flask(__name__)
SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32))
MAX_TOKEN_AGE = 3600  # 1 hour

def generate_token(user_id: int, issued_at: int) -> str:
    """Generate HMAC-signed token with user_id and timestamp."""
    # Pack: user_id (4 bytes unsigned), issued_at (4 bytes unsigned)
    payload = struct.pack('>II', user_id & 0xFFFFFFFF, issued_at & 0xFFFFFFFF)
    mac = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), payload, hashlib.sha256).digest()
    return (payload + mac).hex()

def verify_token(token_hex: str) -> dict:
    """Verify token signature and check expiration."""
    try:
        token_bytes = bytes.fromhex(token_hex)
    except (ValueError, TypeError):
        return None

    if len(token_bytes) != 40:  # 4 + 4 + 32
        return None

    payload = token_bytes[:8]
    provided_mac = token_bytes[8:]

    expected_mac = hmac.new(
        SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(),
        payload, hashlib.sha256
    ).digest()

    if not hmac.compare_digest(provided_mac, expected_mac):
        return None

    user_id, issued_at = struct.unpack('>II', payload)

    # Check token expiration - use absolute time comparison
    current_time = int(time.time())

    # Reject tokens issued in the future (clock skew protection)
    if issued_at > current_time + 60:
        return None

    # Reject expired tokens using safe subtraction
    if current_time - issued_at > MAX_TOKEN_AGE:
        return None

    return {'user_id': user_id, 'issued_at': issued_at}

def require_auth(f):
    """Decorator to require valid token authentication."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            abort(401)
        token = auth_header[7:]
        user_info = verify_token(token)
        if user_info is None:
            abort(401)
        request.user_info = user_info
        return f(*args, **kwargs)
    return decorated

# In-memory document store
documents = {
    1: {'title': 'Public Report', 'content': 'Q1 earnings...', 'owner_id': 1},
    2: {'title': 'Secret Plan', 'content': 'Acquisition target...', 'owner_id': 2},
    3: {'title': 'HR Records', 'content': 'Salary data...', 'owner_id': 3},
}

@app.route('/api/login', methods=['POST'])
def login():
    """Simplified login - in production would verify credentials."""
    data = request.get_json()
    if not data or 'user_id' not in data:
        abort(400)
    user_id = int(data['user_id'])
    issued_at = int(time.time())
    token = generate_token(user_id, issued_at)
    return jsonify({'token': token})

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    """Get document - only owner can access."""
    doc = documents.get(doc_id)
    if doc is None:
        abort(404)
    if doc['owner_id'] != request.user_info['user_id']:
        abort(403)
    return jsonify(doc)

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    """Get current user profile."""
    return jsonify({'user_id': request.user_info['user_id']})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
